    if (ch === '"') { inString = true; continue; }
    if (ch === opener) depth += 1;
    else if (ch === closer) {
      depth -= 1;
      if (depth === 0) {
        const parsed = tryParse(raw.slice(start, i + 1));
        if (parsed !== undefined) return parsed;
